export const productsData: Product[] = rawProducts.map((p, index) => {
  const discount = p.compareAtPrice ? Math.round(((p.compareAtPrice - p.price) / p.compareAtPrice) * 100) : 0;
  const slug = p.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');
  const prefix = p.category.substring(0, 3).toUpperCase();
  const SKU = `IWD-${prefix}-${(index + 101).toString()}`;
  
  return {
    _id: `prod-${p.id}`,
    id: `prod-${p.id}`,
    name: p.name,
    slug,
    SKU,
    category: p.category,
    subcategory: p.subcategory,
    brand: 'Interwood',
    description: `The ${p.name} reflects Interwood's commitment to contemporary architecture, ergonomics, and enduring Pakistani craftsmanship. Built using ${p.material.toLowerCase()}, this piece provides exceptional durability and elegant tactile presence. Suitable for modern residences, executive suites, and luxury living spaces.`,
    shortDescription: `Crafted from ${p.material} with precision finishing. Dimensions: ${p.dimensions.length} x ${p.dimensions.width} x ${p.dimensions.height} ${p.dimensions.unit}.`,
    price: p.price,
    compareAtPrice: p.compareAtPrice,
    discount,
    stock: p.stock ?? (12 + (index % 15)),
    stockStatus: 'In Stock',
    images: [p.image, p.image],
    thumbnail: p.image,
    gallery: [p.image, p.image],
    specifications: [
      { label: 'Brand', value: 'Interwood' },
      { label: 'Origin', value: 'Lahore, Pakistan' },
      { label: 'Primary Material', value: p.material },
      { label: 'Color / Finish', value: p.color },
      { label: 'Assembly', value: 'Professional assembly service provided on delivery' },
      { label: 'Care Instructions', value: 'Wipe with a soft dry cloth; avoid abrasive chemical cleaners.' }
    ],
    dimensions: p.dimensions,
    material: p.material,
    color: p.color,
    warranty: '1-Year Structural Warranty (Sample / Demo Data)',
    rating: p.rating ?? (4.7 + ((index % 4) * 0.1)),
    reviewsCount: 8 + (index % 19),
    featured: !!p.featured,
    bestseller: !!p.bestseller,
    newArrival: !!p.newArrival,
    tags: [p.category.toLowerCase(), p.subcategory.toLowerCase(), p.color.toLowerCase(), 'interwood', 'furniture', 'lahore'],
    createdAt: new Date(Date.now() - (index * 86400000)).toISOString()
  };
});

